class Solution:
    def merge(self, intervals: list[list[int]]) -> list[list[int]]:
        # observation:
        # - the intervals gotta be sorted, but sorted by start or end?
        # - the small subproblem is to merge 2 intervals. WHen are tyhey mergeable? end_a >= start_b
        ans = []
        intervals.sort(key = lambda i: i[0])
        for i in range(len(intervals)):
            if i == 0 or ans[-1][1] < intervals[i][0]:
                ans.append(intervals[i])
            else:
                ans[-1][1] = max(ans[-1][1], intervals[i][1])

        return ans
